#!/usr/bin/env python3
# Some portions generated by Codex.
import pathlib,json
p=pathlib.Path(__file__).resolve().parent;arms=['base','depth','resource','both'];ss={a:json.loads((p/'runs'/('profile-'+a)/'profile-summary.json').read_text()) for a in arms}
out=['# Separate actual HTTP profiles','','Four fresh JVMs, one per arm, each with 60 warmups then 30 recorded requests. All 360 requests passed route/count/no-spill/cleanup witnesses. JFR recording and JSON export both use stack depth 128. Clean timing results are unchanged and no profile duration is pooled into them.','','Java execution samples cover all server and Workbench JVM threads. Node CPU is absent; inter-request client setup and metrics are inside the recording window. Native-method samples are separate. Counts below are statistical sample visibility, not exact calls, instructions or wall-time shares. One profile per arm cannot establish a stable difference.','','| Arm | Java samples | TLS-visible samples | Native samples | Sampled allocation weight GB |','|---|---:|---:|---:|---:|']
for a,s in ss.items():out.append(f"| {a} | {s['javaSamples']} | {s['threadLocalVisibleSamples']} | {s['nativeSamples']} | {s['sampledAllocationWeight']/1e9:.2f} |")
out+=['','## ThreadLocal map operations','','These are inclusive sampled frames, which overlap within a sample. Other ThreadLocals still mutate the map; the holder patch does not remove all map operations.','','| Arm | ThreadLocal.set | ThreadLocal.remove | Map.set | Map.remove |','|---|---:|---:|---:|---:|']
for a,s in ss.items():
 m=s['threadLocalMethods'];out.append('| '+a+' | '+' | '.join(str(m.get(k,0)) for k in ['java.lang.ThreadLocal.set','java.lang.ThreadLocal.remove','java.lang.ThreadLocal$ThreadLocalMap.set','java.lang.ThreadLocal$ThreadLocalMap.remove'])+' |')
out+=['','## Nearest ThreadLocal callers','']
for a,s in ss.items():
 out+=['### '+a,''];out.extend(f'- `{k}`: {v} samples.' for k,v in list(s['threadLocalCallers'].items())[:12]);out.append('')
out+=['## Interpretation and limits','','Source-level behavior is clear: read-resource enter/close now updates a field in an owner-free per-thread holder rather than setting/removing the ThreadLocal map entry for each frame. It still performs ThreadLocal lookup and creates the resource frame. The static holder retains a small empty slot per thread/store key; correctness tests require its current frame to clear, so this is not permission to retain the store or finished frame. Sampled allocations do not validate retained-heap behavior.','','The clean factorial found no demonstrated HTTP benefit, so reduced map mutation cannot be presented as saved end-to-end time. Remaining initialization, tracked/observed read scopes, fused attach, binary/NDJSON serialization and binding materialization must be judged by actual-path profiles and independently tested changes, not by disappearing helper names. Do not re-promote the already-inconclusive initializer null-slot tweak simply because its callers remain sampled.','','Sample allocation weights are approximate and can be dominated by rare stack/class events; they are neither exact bytes nor live heap. No per-query allocation or GC causality is inferred. Raw JFR and large full-stack JSON remain local; compact summaries preserve all category counts and top sampled stacks. No new optimization or extra timing round follows automatically.','','## Nearest sampled work categories','','Categories are exclusive by nearest matching frame; they do not assign wall time.','']
for a,s in ss.items():out+=['### '+a,'',json.dumps(s['nearestCategories'],sort_keys=True),'']
(p/'HTTP-PROFILES.md').write_text('\n'.join(out))
